class NoteHolder(private val binding: ItemNoteBinding) : RecyclerView.ViewHolder(binding.root) {
    fun bind(note: Note, onClick: (String) -> Unit) {
        binding.title.text = note.title
        binding.pinned.isVisible = note.isPinned
        binding.root.setOnClickListener { onClick(note.id) }
    }
}

object NoteDiff : DiffUtil.ItemCallback<NoteRow>() {
    override fun areItemsTheSame(a: NoteRow, b: NoteRow) = a.id == b.id
    override fun areContentsTheSame(a: NoteRow, b: NoteRow) = a == b
}
